ALTER TABLE public.candidates ADD COLUMN IF NOT EXISTS latitude double precision, ADD COLUMN IF NOT EXISTS longitude double precision, ADD COLUMN IF NOT EXISTS geocoded_at timestamptz, ADD COLUMN IF NOT EXISTS geocode_source text;
ALTER TABLE public.vacancies ADD COLUMN IF NOT EXISTS latitude double precision, ADD COLUMN IF NOT EXISTS longitude double precision, ADD COLUMN IF NOT EXISTS geocoded_at timestamptz, ADD COLUMN IF NOT EXISTS geocode_source text;
CREATE OR REPLACE FUNCTION public.haversine_km(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision) RETURNS double precision LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN lat1 IS NULL OR lon1 IS NULL OR lat2 IS NULL OR lon2 IS NULL THEN NULL ELSE 2 * 6371 * asin(sqrt(power(sin(radians((lat2-lat1)/2)),2) + cos(radians(lat1))*cos(radians(lat2))*power(sin(radians((lon2-lon1)/2)),2))) END; $$;